//! Rust-native golden tests (no pytest counterpart): the Dynamo adapter's YAML and shlex inputs against the real
//! Python (tests/fixtures/dynamo/{yaml,shlex}_golden.json, generated by gen_goldens.py), now through the core
//! `services::pyyaml` (the exact PyYAML 6.0.3 engine) and `services::shlex`. Values must match `repr()` exactly; YAML
//! error cases must fail too (their exact class and text are pinned by tests/core_pyyaml.rs).
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

mod dynamo_support;
mod switchyard_support;

use dynamo_support::fx;
use nemo_console::services::pyyaml::safe_load_value as safe_load;
use nemo_console::services::shlex::split;
use serde_json::Value;

#[test]
fn yaml_port_matches_pyyaml_goldens() {
    let cases: Vec<Value> = serde_json::from_str(&fx("yaml_golden.json")).unwrap();
    let mut bad = Vec::new();
    for c in &cases {
        let input = c["input"].as_str().unwrap();
        let got = safe_load(input);
        match (c.get("ok"), &got) {
            (Some(want), Ok(v)) if v.repr() == want.as_str().unwrap() => {}
            (None, Err(_)) => {}
            _ => bad.push(format!("{input:?}: got {got:?}, want {c}")),
        }
    }
    assert!(bad.is_empty(), "{}", bad.join("\n"));
}

#[test]
fn shlex_port_matches_python_goldens() {
    let cases: Vec<Value> = serde_json::from_str(&fx("shlex_golden.json")).unwrap();
    for c in &cases {
        let input = c["input"].as_str().unwrap();
        match (c.get("ok"), split(input)) {
            (Some(Value::Array(want)), Ok(got)) => {
                let want: Vec<&str> = want.iter().map(|x| x.as_str().unwrap()).collect();
                assert_eq!(got, want, "{input:?}");
            }
            (None, Err(e)) => assert_eq!(e.0, c["err"].as_str().unwrap(), "{input:?}"),
            (want, got) => panic!("{input:?}: got {got:?}, want {want:?}"),
        }
    }
}

proptest::proptest! {
    #[test]
    fn yaml_loader_never_panics(s in "[a-z0-9 :\\-\\[\\]{}'\"&*!<>|\\n#,.~]{0,64}") {
        let _ = safe_load(&s);
    }

    #[test]
    fn shlex_never_panics(s in "\\PC{0,48}") {
        let _ = split(&s);
    }
}
